const active = () => state.tasks.filter(t=>!['已完成','已取消'].includes(t.status));
const focused = () => active().filter(t=>t.focus);
const waiting = () => active().filter(t=>t.status==='等待他人');
const openMRs = () => state.mrs.filter(m=>!m.done);
const risksOpen = () => state.risks.filter(r=>r.status!=='已闭环');
const monthlyRate = l => Math.round(l.monthly.filter(m=>m.status==='已完成').length/l.monthly.length*100);
const dueText = d => !d?'未设日期':d===TODAY?'今日':d<TODAY?`逾期 ${Math.round((Date.parse(TODAY)-Date.parse(d))/86400000)} 天`:`${Number(d.slice(5,7))}月${Number(d.slice(8))}日`;
const tone = s => ['受阻','高','超期'].includes(s)?'red':['有风险','中','等待他人'].includes(s)?'amber':['已完成','正常','已闭环','低'].includes(s)?'green':'blue';
const summary = () => ({方案:state.variant,页面:VIEW_NAMES[state.view],今日要事:focused().length,收件箱:active().filter(t=>t.status==='收件箱').length,已完成:state.tasks.filter(t=>t.status==='已完成').length,等待:waiting().length,待评审:openMRs().length,开放风险:risksOpen().length,最近操作:state.lastAction});
function updateURL(){const url=new URL(location.href);url.searchParams.set('variant',state.variant);url.searchParams.set('view',state.view);history.replaceState(null,'',url);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200);}
function change(message){state.lastAction=message;render();console.info('prototype-state',summary());}
function navItems(top=false){return Object.entries(VIEW_NAMES).map(([key,label],i)=>`<button data-action="nav" data-view="${key}" class="${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''} title="${label}">${top?'':icon(['grid','list','factory','branch','report','users'][i])}<span class="nav-text">${key==='today'?(top?'总览':'今日工作台'):label}</span>${!top&&key==='tasks'?`<span class="nav-count">${active().length}</span>`:!top&&key==='mr'?`<span class="nav-count">${openMRs().length}</span>`:''}</button>`).join('');}
function brand(){return `<div class="brand"><div class="brand-mark">序</div><div><div class="brand-title">个人工作台</div><small>PERSONAL WORKBENCH</small></div></div>`;}
function render(){
 document.body.className=state.variant==='A'?'theme-a':'theme-b';updateURL();
 const content=state.view==='today'?(state.variant==='A'?VariantA():VariantB()):renderPage();
 document.querySelector('#app').innerHTML=(state.variant==='A'?`<div class="a-shell"><aside class="sidebar">${brand()}<div class="workspace-name">${icon('users')}<span>软件研发 · 我的空间</span></div><div class="nav-label">WORKSPACE</div><nav class="side-nav" aria-label="工作区">${navItems()}</nav><div class="sidebar-note">${icon('leaf')}把精力留给重要的事。<br>七类工作，一个有序的起点。</div><div class="profile"><span class="avatar">我</span><div class="grow">我的工作空间<small>软件研发 · 管理者</small></div><button class="icon-btn" data-action="about" aria-label="原型说明">${icon('settings')}</button></div></aside><main class="a-main"><header class="a-topbar"><div class="crumb">我的空间 <span>/ ${state.view==='today'?'今日':VIEW_NAMES[state.view]}</span></div><div class="row"><button class="search" data-action="search">${icon('search')}<span>搜索任务…</span><span class="key">/</span></button><button class="icon-btn" data-action="alerts" aria-label="查看提醒">${icon('bell')}</button><button class="icon-btn" data-action="quick" aria-label="快速记录">${icon('plus')}</button></div></header><div class="a-content">${content}</div></main></div>`:`<header class="b-topbar">${brand()}<nav class="top-nav" aria-label="工作区">${navItems(true)}</nav><span class="demo-marker"><span class="dot"></span>演示数据</span><button class="icon-btn" data-action="alerts" aria-label="查看提醒">${icon('bell')}</button>${btn(icon('plus')+' 快速记录 <span class="key">N</span>','quick')}<span class="avatar">我</span></header><main class="b-content">${content}</main>`)+Switcher();
}
function Switcher(){const s=summary();return `<div class="prototype-switcher" role="group" aria-label="切换原型方案"><button data-action="variant" aria-label="上一种方案">${icon('left')}</button><div class="switch-label">${state.variant} · ${state.variant==='A'?'今日行动台':'产线指挥台'}<small>需求文档 2 · 临时原型</small></div><button data-action="variant" aria-label="下一种方案">${icon('right')}</button><span class="switch-count">${state.variant==='A'?'01':'02'} / 02</span><button data-action="state" aria-label="查看原型状态" aria-expanded="${state.showState}">${icon('info')}</button></div>${state.showState?`<aside class="state-popover"><h3>当前演示状态</h3><p>全部记录为虚构。两种布局共享内存状态，刷新重置。演示日期：2026-11-06。</p><pre>${esc(JSON.stringify(s,null,2))}</pre></aside>`:''}`;}
function focusPanel(){return `<section class="panel focus-panel"><div class="section-label"><h2>${icon('leaf')} 今日三件要事</h2><span class="hint">${focused().length} / 3 · 少即是多</span></div>${focused().map((t,i)=>`<div class="focus-row"><span class="focus-index">0${i+1}</span><div class="grow"><button class="focus-title" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="focus-meta">${pill(DOMAINS[t.domain],t.domain==='D3'?'blue':'green')}<span>${esc(t.project)}</span><span>·</span><span>${esc(t.status)}</span></div></div><button class="check-btn" data-action="complete" data-id="${t.id}" aria-label="完成${esc(t.title)}"></button></div>`).join('')||'<div class="empty">留一点空白给重要的事。<br>在任务中心点击 ☆，最多选三件要事。</div>'}</section>`;}
function taskRow(t){return `<div class="task-row ${t.status==='已完成'?'completed':''}"><button class="check-btn ${t.status==='已完成'?'done':''}" data-action="complete" data-id="${t.id}" ${t.status==='已完成'?'disabled':''} aria-label="完成${esc(t.title)}">${t.status==='已完成'?icon('check'):''}</button><div class="grow"><button class="title" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="meta">${pill(DOMAINS[t.domain],t.domain==='D3'?'blue':'')}<span>${esc(t.project)}</span>${t.recurring?`<span>↻ ${esc(t.recurring)}</span>`:''}${t.status==='收件箱'?pill('未整理'):t.status==='等待他人'?pill('等待他人','amber'):''}</div></div><span class="due" style="${t.due&&t.due<TODAY&&t.status!=='已完成'?'color:var(--red)':''}">${dueText(t.due)}</span>${!['已完成','已取消','收件箱','等待他人'].includes(t.status)?`<button class="star-btn ${t.focus?'selected':''}" data-action="focus" data-id="${t.id}" aria-label="${t.focus?'取消':'设为'}今日要事" aria-pressed="${!!t.focus}">${t.focus?'★':'☆'}</button>`:''}</div>`;}
function waitItems(){return waiting().map(t=>`<div class="wait-item"><button class="wait-title" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="wait-meta"><span class="avatar ${t.domain==='D4'?'lilac':''}">${esc(t.person.slice(-1))}</span><span>${esc(t.person)}</span><span style="margin-left:auto">${pill(dueText(t.reply),t.reply<TODAY?'red':'')}</span></div></div>`).join('')||'<div class="empty">暂无等待事项</div>';}
function VariantA(){const blocked=state.lines.flatMap(l=>l.weekly).filter(w=>w.status==='受阻').length;const overdueWait=waiting().filter(t=>t.reply<TODAY).length;const nextActions=active().filter(t=>!t.focus&&['待办','进行中'].includes(t.status));return `
 <div class="a-greeting"><div><div class="eyebrow">FRIDAY, NOVEMBER 06</div><h1>早上好，开始有序的一天。</h1><p>先完成重要的事，再给每一条线一个明确的下一步。</p></div><div class="date-block"><strong>2026年11月6日 · 周五</strong>第 45 周 · 演示工作日</div></div>
 <div class="daily-strip">${icon('leaf')}<span>今天有 <strong>${active().filter(t=>t.due===TODAY).length} 项待办</strong>，<strong>${overdueWait} 项等待超期</strong>，${blocked} 项产线重点受阻，<strong>${risksOpen().filter(r=>r.level==='高').length} 项高风险</strong>待跟进。</span><button class="text-btn" data-action="alerts">查看提醒 ${icon('arrow')}</button></div>
 <div class="a-grid"><div class="stack">${focusPanel()}<section class="panel"><header class="panel-head"><h2>接下来的行动 <span class="count">${nextActions.length}</span></h2><button class="text-btn" data-action="nav" data-view="tasks">全部任务 ${icon('arrow')}</button></header>${nextActions.map(taskRow).join('')||'<div class="empty">暂无其他待办或进行中事项</div>'}<div class="week-note"><div class="row">${icon('report')}<p>周五，给这一周留一份记录。<br><small class="muted">日常完成的工作，会成为总结的素材。</small></p></div><button class="text-btn" data-action="nav" data-view="report">整理周报 ${icon('arrow')}</button></div></section><section class="panel"><header class="panel-head"><h2>产线一瞥 <span class="count">11 月重点</span></h2><button class="text-btn" data-action="nav" data-view="lines">进入产线 ${icon('arrow')}</button></header><div class="panel-body">${state.lines.map(l=>`<div class="line-mini" role="button" tabindex="0" data-action="line" data-id="${l.id}"><div class="between"><h3>${l.name} <small class="muted">· ${l.owner}</small></h3><span class="row">${pill(l.weekly.some(w=>w.status==='受阻')?'需协调':l.weekly.some(w=>w.status==='有风险')?'需关注':'按计划',l.weekly.some(w=>w.status==='受阻')?'red':l.weekly.some(w=>w.status==='有风险')?'amber':'green')}<small class="muted">${monthlyRate(l)}%</small></span></div><div class="progress ${l.tone}"><i style="width:${monthlyRate(l)}%"></i></div><div class="subline">月重点 ${l.monthly.filter(m=>m.status==='已完成').length}/${l.monthly.length} 已完成 · 周重点 ${l.weekly.filter(w=>w.status==='已完成').length}/${l.weekly.length} 已完成 · 开放风险 ${risksOpen().filter(r=>r.line===l.id).length}</div></div>`).join('')}</div></section></div>
 <aside class="stack" style="align-content:start"><section class="panel"><header class="panel-head"><h2>等待回音 <span class="count">${waiting().length}</span></h2>${icon('clock')}</header><div class="panel-body">${waitItems()}</div></section><section class="panel"><header class="panel-head"><h2>待我评审 <span class="count">${openMRs().length}</span></h2><button class="text-btn" data-action="nav" data-view="mr">查看全部 ${icon('arrow')}</button></header><div class="panel-body">${openMRs().slice(0,2).map(m=>`<div class="mr-mini"><div class="between" style="align-items:flex-start"><button data-action="mr" data-id="${m.id}">${esc(m.title)}</button>${pill(`${m.days} 天`,m.days>2?'red':'')}</div><p class="meta"><span class="mono">${m.number}</span> · ${esc(m.project)}<br><span style="display:inline-block;margin-top:4px">${esc(m.author)} · Open · 演示快照</span></p></div>`).join('')||'<div class="empty">待评审已清空</div>'}</div></section><section class="panel"><header class="panel-head"><h2>今天的节奏</h2>${icon('calendar')}</header><div class="panel-body"><div class="timeline"><span class="time">10:00</span><div><p>研发方案复核</p><small>给技术工作留一段专注时间</small></div></div><div class="timeline"><span class="time">14:30</span><div><p>三产线周进展回顾</p><small>关注受阻项与本周遗留</small></div></div><div class="timeline" style="border:0"><span class="time">17:00</span><div><p>整理中心周总结</p><small>基于已完成记录生成素材</small></div></div><small class="muted" style="font-size:9px">虚构日程示例 · 未连接日历或提醒服务</small></div></section><div class="day-end">忙而有序，进而有据。</div></aside></div>`;}
function lineBoard(l){const n=risksOpen().filter(r=>r.line===l.id).length;return `<article class="b-line"><div class="b-line-top"><div class="between"><h3>${l.name}</h3><span class="avatar ${l.id==='B'?'blue':l.id==='C'?'lilac':''}" style="width:24px;height:24px;font-size:9px">${l.owner.slice(-1)}</span></div><div class="line-code">${l.code}</div></div><div class="b-line-progress"><div class="between"><span class="muted">11 月重点完成率</span><span class="big">${monthlyRate(l)}<small style="font-size:11px">%</small></span></div><div class="progress ${l.tone}"><i style="width:${monthlyRate(l)}%"></i></div><div class="muted" style="font-size:9px">${l.monthly.filter(m=>m.status==='已完成').length} / ${l.monthly.length} 项完成 · ${l.owner}</div><div class="distribution">${['正常','有风险','受阻','已完成'].map(s=>{const count=l.weekly.filter(w=>w.status===s).length;return count?`<span><i class="dot" style="color:${s==='正常'?'#6c9c87':s==='有风险'?'#b59060':s==='受阻'?'#bf7b72':'#8497bd'}"></i>${s.replace('已','')} ${count}</span>`:''}).join('')}</div></div><div class="b-week-items">${l.weekly.map(w=>`<div class="b-week-item"><button data-action="progress" data-line="${l.id}" data-id="${w.id}">${esc(w.title)}</button><p>${esc(w.note)}</p>${pill(w.status,tone(w.status))}${w.carry?'<small class="muted" style="font-size:8px;margin-left:5px">上周遗留</small>':''}</div>`).join('')}</div><div class="b-line-footer"><span>${n?`${n} 项开放风险`:'无开放风险'}</span><button data-action="line" data-id="${l.id}">查看产线 ${icon('right')}</button></div></article>`;}
function riskTable(){return `<div class="table-wrap"><table class="risk-table"><thead><tr><th>风险与影响</th><th>产线 / 负责人</th><th>等级</th><th>目标闭环</th><th>状态</th><th></th></tr></thead><tbody>${state.risks.map(r=>`<tr><td><button data-action="risk" data-id="${r.id}" style="text-align:left;padding:0">${esc(r.title)}</button>${r.escalated?'<br><small class="muted" style="font-size:9px">已升级协调</small>':''}</td><td>产线 ${r.line}<br><small class="muted">${r.owner}</small></td><td>${pill(r.level,tone(r.level))}</td><td style="${r.due<TODAY&&r.status!=='已闭环'?'color:var(--red)':''}">${r.status==='已闭环'?'11月05日闭环':dueText(r.due)}</td><td>${pill(r.status,tone(r.status))}</td><td><button class="text-btn" data-action="risk" data-id="${r.id}">${r.status==='已闭环'?'查看记录':'处理'} ${icon('right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function VariantB(){const weekItems=state.lines.flatMap(l=>l.weekly);return `<div class="b-intro"><div><div class="eyebrow">OPERATIONS OVERVIEW / WEEK 45</div><h1>把握全局，推动每一步。</h1><p>2026年11月6日 · 周五 <span style="margin:0 9px;color:#ccd2df">|</span>11月02日 — 11月08日 · 演示周期</p></div>${btn(icon('report')+' 生成周报素材','nav','data-view="report"')}</div>
 <section class="b-overview"><div class="overview-main"><div class="eyebrow">本周产线重点</div><strong>${weekItems.filter(w=>w.status==='已完成').length}<span style="font-size:14px;font-weight:400;color:#9fafd0"> / ${weekItems.length}</span></strong><p>项已完成 · 重点先行，风险跟进</p></div><button class="stat-cell" data-action="alerts"><span class="stat-label">${icon('alert')}需介入的重点</span><span class="stat-value">${weekItems.filter(w=>['受阻','有风险'].includes(w.status)).length}<small>项</small></span><p>${weekItems.filter(w=>w.status==='受阻').length} 受阻 · ${weekItems.filter(w=>w.status==='有风险').length} 有风险</p></button><button class="stat-cell" data-action="nav" data-view="mr"><span class="stat-label">${icon('branch')}待我评审</span><span class="stat-value">${openMRs().length}<small>个 MR</small></span><p>${openMRs().filter(m=>m.days>2).length} 项超过 2 天</p></button><button class="stat-cell" data-action="tasks-wait"><span class="stat-label">${icon('clock')}等待他人</span><span class="stat-value">${waiting().length}<small>项</small></span><p>${waiting().filter(t=>t.reply<TODAY).length} 项回复超期</p></button></section>
 <div class="b-grid"><div><div class="section-label"><div class="row"><h2>三产线 · 本周进展</h2>${pill('W45','blue')}</div><button class="text-btn" data-action="nav" data-view="lines">月 / 周重点 ${icon('arrow')}</button></div><div class="b-lines">${state.lines.map(lineBoard).join('')}</div><section class="panel b-bottom"><header class="panel-head"><h2>${icon('alert')} 风险登记册 <span class="count">${risksOpen().length} 项开放</span></h2><span class="muted" style="font-size:10px">独立跟踪 · 不随任务完成自动关闭</span></header>${riskTable()}</section></div><aside class="stack" style="align-content:start">${focusPanel()}<section class="panel"><header class="panel-head"><h2>需要一个回音 <span class="count">${waiting().length}</span></h2>${icon('clock')}</header><div class="panel-body">${waitItems()}</div></section><section class="panel"><header class="panel-head"><h2>最近进展</h2>${icon('activity')}</header><div class="b-log">${state.logs.slice(0,3).map(l=>`<div class="log-item"><strong>${esc(l.text)}</strong><time>${esc(l.time)} · 演示记录</time></div>`).join('')}</div></section></aside></div><footer class="b-footer"><span class="row"><span class="dot" style="color:#7c9a8c"></span>本机演示 · 内存状态，刷新重置</span><span>GitLab 快照为虚构 · 未连接外部服务 <button data-action="about" class="text-btn" style="font-size:9px;margin-left:10px">数据说明 ${icon('info')}</button></span></footer>`;}
function pageLead(title,description,action=''){return `<div class="page-lead between"><div><div class="eyebrow">MY WORKSPACE / ${esc(state.view.toUpperCase())}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function renderPage(){return ({tasks:TasksPage,lines:LinesPage,mr:MRPage,report:ReportPage,people:PeoplePage})[state.view]();}
function filteredTasks(){return state.tasks.filter(t=>{
 const statusOK=state.taskFilter==='all'||(state.taskFilter==='active'&&!['已完成','已取消'].includes(t.status))||(state.taskFilter==='done'&&t.status==='已完成')||(state.taskFilter==='inbox'&&t.status==='收件箱')||(state.taskFilter==='waiting'&&t.status==='等待他人');
 return statusOK&&(state.domain==='all'||t.domain===state.domain)&&(!state.query||[t.title,t.note,t.source,t.project,t.person||''].join(' ').toLowerCase().includes(state.query.toLowerCase()));
});}
function tasksContent(){const tasks=filteredTasks();if(!tasks.length)return '<div class="panel empty">没有符合条件的任务。试试其他筛选，或记录一件新事。</div>';
 if(state.taskLayout==='board')return `<div class="task-board">${['收件箱','待办','进行中','等待他人',...(tasks.some(t=>t.status==='已完成')?['已完成']:[])].map(status=>`<section class="board-col"><h3>${status}<small class="muted">${tasks.filter(t=>t.status===status).length}</small></h3>${tasks.filter(t=>t.status===status).map(t=>`<button class="board-card" data-action="task" data-id="${t.id}">${pill(DOMAINS[t.domain])}<p>${esc(t.title)}</p><small>${esc(t.project)} · ${dueText(t.due)}</small></button>`).join('')}</section>`).join('')}</div>`;
 if(state.taskLayout==='quadrant')return `<div class="quadrants">${[[true,true,'重要且紧急','优先处理'],[true,false,'重要不紧急','安排专注时间'],[false,true,'紧急不重要','协调或委派'],[false,false,'不重要不紧急','稍后整理']].map(([important,urgent,title,hint])=>`<section class="quadrant"><h3>${title}</h3><p>${hint}</p>${tasks.filter(t=>t.important===important&&t.urgent===urgent).map(taskRow).join('')||'<div class="empty">暂无事项</div>'}</section>`).join('')}</div>`;
 return `<section class="panel">${tasks.map(taskRow).join('')}<div class="activity">${tasks.length} 项任务 · 点击标题查看详情 · ☆ 可设为今日要事</div></section>`;
}
function TasksPage(){return pageLead('把零散的事，放回有序。','七类工作共用一份任务清单；用状态和优先级安排下一步。',btn(icon('plus')+' 快速记录','quick','','primary'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="task-search" placeholder="搜索标题、描述、备注…" aria-label="搜索任务" value="${esc(state.query)}"></label><select id="domain-filter" aria-label="工作域"><option value="all">全部工作域</option>${Object.entries(DOMAINS).map(([k,v])=>`<option value="${k}" ${state.domain===k?'selected':''}>${v}</option>`).join('')}</select><select id="status-filter" aria-label="任务状态">${[['active','未完成'],['all','全部任务'],['inbox','收件箱'],['waiting','等待他人'],['done','已完成']].map(([k,v])=>`<option value="${k}" ${state.taskFilter===k?'selected':''}>${v}</option>`).join('')}</select><div class="segmented" style="margin-left:auto">${[['list','列表'],['board','看板'],['quadrant','四象限']].map(([k,v])=>`<button data-action="layout" data-layout="${k}" class="${state.taskLayout===k?'active':''}">${v}</button>`).join('')}</div></div><div id="task-results">${tasksContent()}</div>`;}
function MRPage(){const list=state.mrs.filter(m=>state.mrProject==='all'||m.project===state.mrProject);return pageLead('让每一次评审，都有着落。','管理评审任务与停留时长。完成评审会在本地演示记录中生成一条工作事项。')+`<div class="notice neutral" style="margin-bottom:21px">${icon('info')}GitLab 未连接，以下是虚构的 Open MR 快照。积压阈值为超过 2 天；不会提交 Approval 或合并代码。</div><div class="toolbar"><select id="mr-project" aria-label="按项目筛选 MR"><option value="all">全部项目</option>${[...new Set(state.mrs.map(m=>m.project))].map(p=>`<option ${state.mrProject===p?'selected':''}>${esc(p)}</option>`).join('')}</select><span class="muted" style="font-size:11px">${openMRs().length} 项待评审 · ${openMRs().filter(m=>m.days>2).length} 项积压</span></div><section class="panel">${list.map(m=>`<article class="mr-card ${m.done?'done':''}"><div class="mr-number">${m.number}</div><div class="grow"><h3><button data-action="mr" data-id="${m.id}" style="padding:0;text-align:left">${esc(m.title)}</button></h3><p>${esc(m.project)} · ${m.author} · 提交于 ${m.created}<br><span class="mono">${esc(m.branch)}</span></p><div class="mr-actions">${pill(m.done?'本地已记录评审完成':`停留 ${m.days} 天`,m.done?'green':m.days>2?'red':'')}${m.done?'':btn('记录评审完成','review-mr',`data-id="${m.id}"`,'small')}${btn('查看快照','mr',`data-id="${m.id}"`,'small ghost')}</div></div></article>`).join('')}</section>`;}
function LinesPage(){return pageLead('盯住重点，让进展可见。','三条产线的周期重点是主体；执行由负责人推进，个人聚焦跟进与协调。')+`<div class="toolbar"><div class="segmented"><button data-action="line-period" data-period="week" class="${state.linePeriod==='week'?'active':''}">周重点</button><button data-action="line-period" data-period="month" class="${state.linePeriod==='month'?'active':''}">月重点</button></div><span class="muted" style="font-size:11px">${state.linePeriod==='week'?'2026 W45 · 11月02日 — 11月08日':'2026年11月 · 月重点完成率 = 已完成条目 / 全部条目'}</span><span class="muted" style="font-size:10px;margin-left:auto">固定演示周期</span></div><div class="line-detail-grid">${state.lines.map(l=>`<section class="line-full" id="line-${l.id}"><div class="between"><h2>${l.name}</h2><span class="avatar ${l.id==='B'?'blue':l.id==='C'?'lilac':''}">${l.owner.slice(-1)}</span></div><p class="muted" style="font-size:10px;margin-top:9px">${l.owner} · 本月已完成 ${l.monthly.filter(m=>m.status==='已完成').length} / ${l.monthly.length} · ${monthlyRate(l)}%</p><div class="progress ${l.tone}"><i style="width:${monthlyRate(l)}%"></i></div><div class="line-full-items">${(state.linePeriod==='week'?l.weekly:l.monthly).map(w=>`<article class="line-full-item"><h3>${w.title}</h3><p>${state.linePeriod==='week'?`关联月重点：${w.parent}<br>`:''}目标：${w.goal}</p><div class="row">${pill(w.status,tone(w.status))}${state.linePeriod==='month'?`<small>条目完成度 ${w.pct}%</small>`:''}${w.carry?pill('上周遗留','amber'):''}</div>${w.note?`<p>${esc(w.note)}</p>`:''}<small>更新：${w.updated||'11-05 16:00'} · ${l.owner}</small><button class="text-btn" style="margin-top:10px" data-action="progress" data-line="${l.id}" data-id="${w.id}" data-period="${state.linePeriod}">更新进展 ${icon('arrow')}</button></article>`).join('')}</div><div class="divider" style="padding-top:13px;margin-top:7px"><button class="text-btn" data-action="line" data-id="${l.id}">查看该线风险与概况 ${icon('right')}</button></div></section>`).join('')}</div><section class="panel" style="margin-top:23px"><header class="panel-head"><h2>风险登记册 <span class="count">${risksOpen().length} 项开放</span></h2><span class="muted" style="font-size:10px">高等级与超期风险优先关注</span></header>${riskTable()}</section>`;}
function completedForPeriod(){const start=state.reportPeriod==='month'?'2026-11-01':'2026-11-02';const end=state.reportPeriod==='month'?'2026-11-30':'2026-11-08';return state.tasks.filter(t=>t.status==='已完成'&&t.completed>=start&&t.completed<=end&&!['D4','D5'].includes(t.domain));}
function generateReport(){const completed=completedForPeriod();const period=state.reportPeriod==='month'?'2026年11月':'2026年第45周（11.02—11.08）';const parts=[`# ${period}工作总结素材`,`> 虚构演示数据；按本地记录拼接，非 AI 成稿。请人工核对后使用。`,'## 已完成工作'];for(const [key,name]of Object.entries(DOMAINS)){const ts=completed.filter(t=>t.domain===key);if(ts.length)parts.push(`### ${name}`,...ts.map(t=>`- ${t.title}（完成 ${t.completed}；来源：${t.source}）`));}if(!completed.length)parts.push('- 本周期暂无可导出的已完成事项。');parts.push('## 产线进展');for(const l of state.lines){const items=state.reportPeriod==='month'?l.monthly:l.weekly;parts.push(`### ${l.name} · ${l.owner}`,`- 月重点：${l.monthly.filter(m=>m.status==='已完成').length}/${l.monthly.length} 项完成（${monthlyRate(l)}%）。`,...items.map(w=>`- [${w.status}] ${w.title}；${w.note||w.goal}${w.status==='受阻'||w.status==='有风险'?'；需重点跟进':''}`));}parts.push('## 风险与协调',...risksOpen().map(r=>`- [${r.level} / ${r.status}] 产线 ${r.line}：${r.title}；负责人 ${r.owner}；目标闭环 ${r.due}。`),'### 本周期风险变化',`- 新增 ${state.risks.filter(r=>r.created&&r.created>=(state.reportPeriod==='month'?'2026-11-01':'2026-11-02')).length} 项（仅统计有新增日期记录的条目）。`,`- 闭环 ${state.risks.filter(r=>r.closed&&r.closed>=(state.reportPeriod==='month'?'2026-11-01':'2026-11-02')).length} 项。`,'## 下阶段关注',...waiting().filter(t=>!['D4','D5'].includes(t.domain)).map(t=>`- 等待${t.person}：${t.waitFor}；预期回复 ${t.reply}。`),'---','人员管理与招聘记录默认排除；没有执行真实来源同步或 AI 调用。');return parts.join('\n\n');}
function ReportPage(){const completed=completedForPeriod();return pageLead('把日常记录，变成一周的交代。','从已完成任务和产线进展生成素材，再由你编辑成中心总结。')+`<div class="report-grid"><aside class="panel report-summary"><h2>选择总结周期</h2><div class="segmented" style="margin-top:18px"><button data-action="report-period" data-period="week" class="${state.reportPeriod==='week'?'active':''}">本周</button><button data-action="report-period" data-period="month" class="${state.reportPeriod==='month'?'active':''}">本月</button></div><p>${state.reportPeriod==='week'?'11月02日 — 11月08日':'11月01日 — 11月30日'}<br>2026年 · 固定演示周期</p><div class="report-stat"><span>可导出完成事项</span><strong>${completed.length}</strong></div><div class="report-stat"><span>产线重点摘要</span><strong>3 条产线</strong></div><div class="report-stat"><span>开放风险</span><strong>${risksOpen().length}</strong></div><p>按七个工作域分组；产线进展独立成节。人员、招聘敏感记录默认排除。</p>${btn(icon('report')+' 生成素材初稿','generate-report','','primary')}<div class="notice neutral" style="margin-top:21px;font-size:10px;align-items:flex-start">${icon('info')}规则拼接的素材，未经 AI 润色。正式总结模板尚待需求确认。</div></aside><section class="panel report-editor"><div class="between"><h2>总结素材 · 可编辑</h2><span class="badge">Markdown</span></div><textarea id="report-draft" aria-label="总结素材正文" placeholder="点击「生成素材初稿」，将本周期的工作与产线进展汇总在这里。">${esc(state.reportDraft)}</textarea><div class="between"><small class="muted">仅内存保存 · 导出文件由浏览器下载</small><div class="row">${btn(icon('copy')+' 复制','copy-report','','small')}${btn(icon('download')+' 导出 .md','download-report','','small primary')}</div></div></section></div>`;}
function PeoplePage(){return pageLead('关注事，也关注人。','人员与招聘为 P1 功能，本页只验证轻量记录与跟进入口。')+`<div class="notice neutral people-note">${icon('info')}全部人员信息为虚构。此原型没有数据保护、登录或存储能力，请勿录入真实人员信息。</div><div class="people-grid"><section class="panel"><header class="panel-head"><h2>人员与 1:1</h2>${pill('虚构示例')}</header><article class="person-record"><div class="row"><span class="avatar lilac">乙</span><h3>同事乙 · 嵌入式开发</h3></div><p>最近沟通：11月03日<br>讨论要点：下月培养方向与资源支持。<br>下一步：等待本人反馈培养目标。</p>${btn('查看关联跟进','task','data-id="t5"','small')}</article><article class="person-record"><div class="row"><span class="avatar blue">丙</span><h3>同事丙 · 平台开发</h3></div><p>最近沟通：11月03日<br>讨论要点：当前任务负荷与技术成长。<br>下一步：下次沟通前回看行动记录。</p>${btn('查看沟通记录','task','data-id="d3"','small')}</article></section><section class="panel"><header class="panel-head"><h2>招聘跟进</h2>${pill('P1 · 轻量示意')}</header><article class="person-record"><div class="between"><h3>嵌入式软件工程师 · HC 1</h3>${pill('招聘中','blue')}</div><p>候选人甲（虚构）<br>阶段：初面通过 → 待安排复面<br>意向时间：11月09日，等待面试官确认。</p>${btn('查看面试安排','task','data-id="t6"','small')}</article><article class="person-record"><h3>从记录到行动</h3><p>后续正式版本可补充候选人阶段流转、面试提醒和 1:1 历史记录。本次不模拟完整 HR 系统。</p></article></section></div>`;}
const dialog=document.querySelector('#dialog');
function openDialog(title,body,footer='',drawer=false){dialog.className=drawer?'drawer':'';dialog.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-foot">${footer}</footer>`:''}`;if(!dialog.open)dialog.showModal();}
function field(label,html){return `<label class="field"><span>${label}</span>${html}</label>`;}
function openQuick(){openDialog('快速记录',`<p>先记下来，再安排。只填一句话，就能放进收件箱。</p><form id="quick-form">${field('想记下什么？','<input name="title" id="quick-title" placeholder="例如：下周与负责人确认联调窗口" required maxlength="140" autofocus>')}<p class="field-note">录入后进入「收件箱」，无需先决定所属工作域。</p><div class="dialog-foot" style="padding:20px 0 0;margin-top:24px">${btn('取消','close')}<button class="button primary" type="submit">${icon('plus')} 放入收件箱</button></div></form>`);}
function openTask(id){const t=state.tasks.find(t=>t.id===id);openDialog('任务详情',`${pill(DOMAINS[t.domain],tone(t.status))}<h1 class="detail-title">${esc(t.title)}</h1><div class="row">${pill(t.status,tone(t.status))}${t.focus?pill('今日要事','green'):''}${t.recurring?pill(`↻ ${t.recurring}`):''}</div><dl class="detail-meta"><dt>截止日期</dt><dd>${t.due||'未设定'} ${t.due&&t.due<TODAY&&t.status!=='已完成'?pill(dueText(t.due),'red'):''}</dd><dt>所属项目</dt><dd>${esc(t.project)}</dd><dt>优先级</dt><dd>${t.important?'重要':'不重要'} · ${t.urgent?'紧急':'不紧急'}</dd><dt>来源引用</dt><dd>${esc(t.source)}</dd>${t.person?`<dt>等待对象</dt><dd>${esc(t.person)}</dd><dt>等待内容</dt><dd>${esc(t.waitFor)}</dd><dt>预期回复</dt><dd>${esc(t.reply)}</dd>`:''}${t.completed?`<dt>完成日期</dt><dd>${t.completed}</dd>`:''}</dl><div class="detail-note"><small>描述 / 备注</small>${esc(t.note||'暂无备注')}</div><div class="detail-actions">${!['已完成','已取消'].includes(t.status)?`${btn(icon('check')+' 标记完成','complete',`data-id="${t.id}"`,'primary')}${btn('编辑状态与委派信息','edit-task',`data-id="${t.id}"`)}${!['等待他人','收件箱'].includes(t.status)?btn(t.focus?'移出今日要事':'设为今日要事','focus',`data-id="${t.id}"`):''}`:''}</div><p class="field-note" style="margin-top:24px">操作只改变本地演示状态。来源系统、产线风险与外部评审状态独立。</p>`,'',true);}
function openEditTask(id){const t=state.tasks.find(t=>t.id===id);const isWait=t.status==='等待他人';openDialog('安排下一步',`<form id="task-form" data-id="${id}">${field('任务标题',`<input name="title" value="${esc(t.title)}" required maxlength="140">`)}<div class="form-grid">${field('工作域',`<select name="domain">${Object.entries(DOMAINS).map(([k,v])=>`<option value="${k}" ${k===t.domain?'selected':''}>${v}</option>`).join('')}</select>`)}${field('状态',`<select name="status" id="edit-status">${['收件箱','待办','进行中','等待他人','已完成','已取消'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select>`)}${field('截止日期',`<input name="due" type="date" value="${t.due}">`)}</div><div class="row" style="margin-bottom:20px;gap:22px"><label class="check-label"><input type="checkbox" name="important" ${t.important?'checked':''}>重要</label><label class="check-label"><input type="checkbox" name="urgent" ${t.urgent?'checked':''}>紧急</label></div><div id="wait-fields" class="${isWait?'':'hidden'}">${field('等待对象 *',`<input name="person" value="${esc(t.person||'')}" ${isWait?'required':''}>`)}${field('等待内容 *',`<textarea name="waitFor" ${isWait?'required':''}>${esc(t.waitFor||'')}</textarea>`)}${field('预期回复日期 *',`<input name="reply" type="date" value="${t.reply||''}" ${isWait?'required':''}>`)}</div>${field('备注',`<textarea name="note">${esc(t.note||'')}</textarea>`)}<div class="dialog-foot" style="padding:18px 0 0">${btn('取消','close')}<button type="submit" class="button primary">保存安排</button></div></form>`);}
function openMR(id){const m=state.mrs.find(m=>m.id===id);openDialog('MR 评审快照',`${pill('虚构 GitLab 快照','blue')}<h1 class="detail-title">${m.number} ${esc(m.title)}</h1><dl class="detail-meta"><dt>项目</dt><dd>${m.project}</dd><dt>分支</dt><dd class="mono">${esc(m.branch)}</dd><dt>作者 / 提交</dt><dd>${m.author} · ${m.created}</dd><dt>停留时长</dt><dd>${m.days} 天 ${m.days>2?pill('超过 2 天阈值','red'):''}</dd><dt>来源状态</dt><dd>Open · 虚构快照</dd><dt>本地记录</dt><dd>${m.done?'评审已完成':'待我评审'}</dd></dl><p>需求文档尚未提供 GitLab 地址与可用接口。本原型不提供假跳转；正式接入后在这里打开真实 MR。</p>`,m.done?btn('关闭','close'):btn('记录评审完成','review-mr',`data-id="${id}"`,'primary'));}
function openLine(id){const l=state.lines.find(l=>l.id===id);const risks=state.risks.filter(r=>r.line===id);openDialog(`${l.name} · 重点与风险概况`,`<p>${l.owner}负责执行，个人工作台跟踪进展与协调事项。</p><div class="detail-note"><small>11月月重点完成率</small><strong style="font-size:24px">${monthlyRate(l)}%</strong> · ${l.monthly.filter(m=>m.status==='已完成').length}/${l.monthly.length} 项完成<br>完成率按完成条目数计算，单条目的完成度单独记录。</div><h3 style="margin-bottom:12px">本周重点</h3>${l.weekly.map(w=>`<div class="wait-item"><div class="between"><span>${w.title}</span>${pill(w.status,tone(w.status))}</div><p class="field-note">${esc(w.note)}</p><button class="text-btn" data-action="progress" data-line="${id}" data-id="${w.id}">更新进展 ${icon('right')}</button></div>`).join('')}<h3 style="margin-top:20px">风险记录</h3>${risks.map(r=>`<div class="wait-item"><div class="between"><span>${esc(r.title)}</span>${pill(r.level,tone(r.level))}</div><p class="field-note">${r.status} · ${r.owner} · ${r.due}</p><button class="text-btn" data-action="risk" data-id="${r.id}">查看风险 ${icon('right')}</button></div>`).join('')||'<p class="field-note">暂无风险</p>'}`,btn('进入产线重点','nav','data-view="lines"','primary'));}
function openProgress(lineId,itemId,period='week'){const l=state.lines.find(l=>l.id===lineId);const item=(period==='month'?l.monthly:l.weekly).find(w=>w.id===itemId);openDialog('更新产线进展',`<p>${l.name} · ${l.owner}<br>${item.title}</p><form id="progress-form" data-line="${lineId}" data-id="${itemId}" data-period="${period}">${field('进展状态',`<select name="status">${(period==='month'?['未开始','进行中','受阻','已完成','取消']:['正常','有风险','受阻','已完成']).map(s=>`<option ${item.status===s?'selected':''}>${s}</option>`).join('')}</select>`)}${period==='month'?field('条目完成度（0—100%）',`<input type="number" name="pct" min="0" max="100" step="1" value="${item.pct}" required>`):''}${field('本次进展说明 *',`<textarea name="note" required maxlength="1000">${esc(item.note||'')}</textarea>`)}<div class="notice neutral" style="font-size:11px">${icon('info')}进展在两种布局中共享。关联风险仍需单独跟踪与闭环。</div><div class="dialog-foot" style="padding:18px 0 0;margin-top:20px">${btn('取消','close')}<button type="submit" class="button primary">保存进展</button></div></form>`);}
function openRisk(id){const r=state.risks.find(r=>r.id===id);openDialog('风险跟踪',`${pill(`${r.level}等级风险`,tone(r.level))}<h1 class="detail-title">${esc(r.title)}</h1><dl class="detail-meta"><dt>产线 / 负责人</dt><dd>产线 ${r.line} · ${r.owner}</dd><dt>状态</dt><dd>${r.status}${r.escalated?' · 已升级协调':''}</dd><dt>影响</dt><dd>${r.impact}</dd><dt>缓解措施</dt><dd>${r.mitigation}</dd><dt>目标闭环</dt><dd>${r.due}${r.due<TODAY&&r.status!=='已闭环'?' · '+dueText(r.due):''}</dd>${r.closed?`<dt>闭环说明</dt><dd>${esc(r.closeNote||r.mitigation)}</dd>`:''}</dl>${r.status==='已闭环'?'<p>已在本地演示记录中闭环。</p>':`<form id="risk-form" data-id="${id}">${field('更新措施 / 闭环依据 *',`<textarea name="note" required>${esc(r.mitigation)}</textarea>`)}${field('风险状态',`<select name="status">${['开放','跟踪中','已闭环'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select>`)}<p class="field-note">任务或周重点完成不会自动关闭此风险。闭环应基于独立的核实依据。</p><div class="dialog-foot" style="padding:18px 0 0;margin-top:20px">${btn('取消','close')}<button type="submit" class="button primary">保存风险记录</button></div></form>`}`);}
function showAlerts(){const ow=waiting().filter(t=>t.reply<TODAY);const bm=state.lines.flatMap(l=>l.weekly.filter(w=>['受阻','有风险'].includes(w.status)).map(w=>({...w,line:l.id})));openDialog('需要关注的事',`<p>基于固定演示日 2026-11-06 计算。未启用系统通知或后台调度。</p>${ow.map(t=>`<div class="wait-item"><div class="between"><span>${esc(t.title)}</span>${pill(dueText(t.reply),'red')}</div><button class="text-btn" data-action="task" data-id="${t.id}">跟进 ${esc(t.person)} ${icon('right')}</button></div>`).join('')}${openMRs().filter(m=>m.days>2).map(m=>`<div class="wait-item"><div class="between"><span>${m.number} ${esc(m.title)}</span>${pill(`停留 ${m.days} 天`,'amber')}</div><button class="text-btn" data-action="mr" data-id="${m.id}">查看评审 ${icon('right')}</button></div>`).join('')}${bm.map(w=>`<div class="wait-item"><div class="between"><span>产线 ${w.line} · ${w.title}</span>${pill(w.status,tone(w.status))}</div><button class="text-btn" data-action="progress" data-line="${w.line}" data-id="${w.id}">更新进展 ${icon('right')}</button></div>`).join('')}${risksOpen().filter(r=>r.level==='高'||r.due<TODAY).map(r=>`<div class="wait-item"><div class="between"><span>${esc(r.title)}</span>${pill(r.level+'等级风险','red')}</div><button class="text-btn" data-action="risk" data-id="${r.id}">处理风险 ${icon('right')}</button></div>`).join('')}`);}
function downloadReport(){if(!state.reportDraft.trim()){toast('请先生成或填写总结素材');return;}const blob=new Blob([state.reportDraft],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`个人工作台-${state.reportPeriod==='week'?'2026-W45':'2026-11'}-演示素材.md`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已请求浏览器下载 Markdown');}
function navigate(view){if(dialog.open)dialog.close();state.view=view;state.showState=false;render();window.scrollTo(0,0);}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id}=el.dataset;
 if(action==='close'){dialog.close();return;}
 if(action==='variant'){state.variant=state.variant==='A'?'B':'A';change('切换到方案 '+state.variant);return;}
 if(action==='state'){state.showState=!state.showState;render();return;}
 if(action==='nav'){navigate(el.dataset.view);return;}
 if(action==='quick'){openQuick();return;}
 if(action==='task'){openTask(id);return;}
 if(action==='edit-task'){openEditTask(id);return;}
 if(action==='complete'){const t=state.tasks.find(t=>t.id===id);if(t.status==='已完成')return;t.status='已完成';t.focus=false;t.completed=TODAY;if(dialog.open)dialog.close();change('完成任务：'+t.title);toast('已完成，记录已加入本周期素材（敏感事项除外）');return;}
 if(action==='focus'){const t=state.tasks.find(t=>t.id===id);if(!t.focus&&focused().length>=3){toast('今日最多三件要事，请先移出一件');return;}t.focus=!t.focus;change(t.focus?'设为今日要事':'移出今日要事');if(dialog.open)openTask(id);return;}
 if(action==='tasks-wait'){state.taskFilter='waiting';navigate('tasks');return;}
 if(action==='layout'){state.taskLayout=el.dataset.layout;render();return;}
 if(action==='mr'){openMR(id);return;}
 if(action==='review-mr'){const m=state.mrs.find(m=>m.id===id);if(m.done)return;m.done=true;state.tasks.push({id:'review-'+id,title:'评审：'+m.title,domain:'D2',status:'已完成',completed:TODAY,due:TODAY,focus:false,important:true,urgent:false,project:m.project,note:'本地演示评审记录，未向 GitLab 提交评审或合并。',source:`MR ${m.number} · 虚构快照`});if(dialog.open)dialog.close();change('记录 MR '+m.number+' 评审完成');toast('已生成一条代码评审完成记录；GitLab 未变更');return;}
 if(action==='line'){openLine(id);return;}
 if(action==='progress'){openProgress(el.dataset.line,id,el.dataset.period||'week');return;}
 if(action==='risk'){openRisk(id);return;}
 if(action==='line-period'){state.linePeriod=el.dataset.period;render();return;}
 if(action==='report-period'){state.reportPeriod=el.dataset.period;state.reportDraft='';render();toast('已切换周期，请重新生成素材');return;}
 if(action==='generate-report'){if(state.reportDraft&&!confirm('重新生成会替换当前编辑的素材，是否继续？'))return;state.reportDraft=generateReport();change('生成'+(state.reportPeriod==='week'?'周':'月')+'报演示素材');return;}
 if(action==='download-report'){downloadReport();return;}
 if(action==='copy-report'){if(!state.reportDraft.trim()){toast('请先生成或填写总结素材');return;}try{await navigator.clipboard.writeText(state.reportDraft);toast('已复制总结素材');}catch{document.querySelector('#report-draft')?.select();toast('未能访问剪贴板，已选中正文，请按 Ctrl+C 复制');}return;}
 if(action==='alerts'){showAlerts();return;}
 if(action==='search'){state.taskFilter='all';navigate('tasks');document.querySelector('#task-search').focus();return;}
 if(action==='about'){openDialog('这是一份设计提案',`<p>根据《个人工作台需求文档2》制作的两种临时 UI 原型，用于比较个人行动与三产线管理的信息优先级。</p><div class="detail-note">A · 今日行动台：个人三件要事优先。<br>B · 产线指挥台：产线进展与协调优先。</div><p>所有任务、人员、产线与 MR 均为虚构。演示工作日固定为 2026-11-06，周为 11-02 至 11-08。</p><p>仅使用内存，无数据持久化、账号鉴权、接口同步、后台提醒、备份恢复或真实 AI。刷新会重置。请勿录入真实内部资料。</p><p>快捷键：N 快速记录，/ 搜索，← → 切换方案。输入或打开对话框时不会抢占快捷键。</p>`,btn('明白了','close','','primary'));}
});
document.addEventListener('input',e=>{
 if(e.target.required)e.target.setCustomValidity('');
 if(e.target.id==='task-search'){state.query=e.target.value;document.querySelector('#task-results').innerHTML=tasksContent();}
 if(e.target.id==='report-draft')state.reportDraft=e.target.value;
});
document.addEventListener('change',e=>{
 if(e.target.id==='domain-filter'){state.domain=e.target.value;render();}
 if(e.target.id==='status-filter'){state.taskFilter=e.target.value;render();}
 if(e.target.id==='mr-project'){state.mrProject=e.target.value;render();}
 if(e.target.id==='edit-status'){const wait=e.target.value==='等待他人';const group=document.querySelector('#wait-fields');group.classList.toggle('hidden',!wait);group.querySelectorAll('input,textarea').forEach(input=>input.required=wait);}
});
document.addEventListener('submit',e=>{
 const form=e.target;const data=new FormData(form);e.preventDefault();
 const blank=[...form.querySelectorAll('input[required],textarea[required]')].find(input=>!input.value.trim());if(blank){blank.setCustomValidity('请填写有效内容，不能只输入空格');blank.reportValidity();return;}
 if(form.id==='quick-form'){const title=data.get('title').trim();if(!title){document.querySelector('#quick-title').setCustomValidity('请输入事项内容');document.querySelector('#quick-title').reportValidity();return;}state.tasks.unshift({id:'new-'+Date.now(),title,domain:'D1',status:'收件箱',due:'',focus:false,important:false,urgent:false,project:'未分类',note:'待整理：请补充工作域、日期与优先级。',source:'快速记录'});dialog.close();state.taskFilter='inbox';state.domain='all';state.query='';state.view='tasks';change('收件箱新增：'+title);toast('已放入收件箱，稍后再整理');}
 if(form.id==='task-form'){const t=state.tasks.find(t=>t.id===form.dataset.id);t.title=data.get('title').trim()||t.title;t.domain=data.get('domain');t.status=data.get('status');t.due=data.get('due');t.important=data.has('important');t.urgent=data.has('urgent');t.note=data.get('note');if(t.status==='等待他人'){t.person=data.get('person').trim();t.waitFor=data.get('waitFor').trim();t.reply=data.get('reply');t.focus=false;}if(['已完成','已取消','收件箱'].includes(t.status))t.focus=false;if(t.status==='已完成')t.completed=TODAY;else delete t.completed;dialog.close();change('更新任务安排：'+t.title);toast('任务安排已更新');}
 if(form.id==='progress-form'){const l=state.lines.find(l=>l.id===form.dataset.line);const monthly=form.dataset.period==='month';const item=(monthly?l.monthly:l.weekly).find(w=>w.id===form.dataset.id);item.status=data.get('status');item.note=data.get('note').trim();item.updated='11-06 10:00';if(monthly)item.pct=item.status==='已完成'?100:Math.min(Number(data.get('pct')),99);state.logs.unshift({time:'刚刚',text:`${l.name}更新：${item.title} · ${item.status}`});dialog.close();change(l.name+'进展更新为'+item.status);toast('进展已更新；关联风险保持独立');}
 if(form.id==='risk-form'){const r=state.risks.find(r=>r.id===form.dataset.id);r.status=data.get('status');r.mitigation=data.get('note').trim();if(r.status==='已闭环'){r.closed=TODAY;r.closeNote=r.mitigation;}state.logs.unshift({time:'刚刚',text:`产线 ${r.line}风险记录：${r.status}`});dialog.close();change('风险更新为'+r.status);toast('已保存本地演示风险记录');}
});
document.addEventListener('keydown',e=>{
 if(dialog.open)return;const editing=e.target.closest('input,textarea,select,[contenteditable]');if(editing||e.ctrlKey||e.altKey||e.metaKey)return;
 if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();state.variant=state.variant==='A'?'B':'A';change('键盘切换到方案 '+state.variant);}
 if(e.key.toLowerCase()==='n'){e.preventDefault();openQuick();}
 if(e.key==='/'){e.preventDefault();state.taskFilter='all';navigate('tasks');document.querySelector('#task-search').focus();}
 if(e.key==='Enter'&&e.target.matches('[role=button][data-action]'))e.target.click();
});
document.addEventListener('input',e=>{if(e.target.id==='quick-title')e.target.setCustomValidity('');});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.variant=p.get('variant')==='B'?'B':'A';state.view=Object.hasOwn(VIEW_NAMES,p.get('view'))?p.get('view'):'today';if(dialog.open)dialog.close();render();});
render();
